"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["57469"],{57422(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.etapa_comeca_antes_da_fase","status":422,"titulo":"A etapa come\xe7a antes da fase que a abriga"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.etapa_comeca_antes_da_fase","requisitos":[],"oQueAconteceu":["O in\xedcio declarado para uma etapa \xe9 anterior ao in\xedcio da fase do cronograma em que\\nela acontece. A etapa \xe9 parte da fase, ent\xe3o o per\xedodo dela cabe dentro do per\xedodo da\\nfase. A mensagem de detalhe cita a etapa, o in\xedcio dela e o in\xedcio da fase. A recusa\\nsai com **422**.","S\xf3 se compara o que os dois lados declararam: fase sem per\xedodo n\xe3o cont\xe9m nada, e\\netapa sem per\xedodo acontece no per\xedodo da fase. In\xedcio igual ao da fase passa. A etapa que\\ndeclara apenas um dos extremos herda o outro da fase.","A regra vale ao definir as etapas, ao definir o cronograma (que pode mover a fase por\\nbaixo de etapas j\xe1 datadas) e, como defesa, na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, para que nenhuma vers\xe3o congele uma prova marcada\\npara antes da fase que a cont\xe9m."],"comoResolver":["Alinhe as datas: ajuste o in\xedcio da etapa\\n(`PUT /api/selecao/processos-seletivos/{id}/etapas`) ou antecipe o in\xedcio da fase\\n(`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`), conforme o edital.\\nRepita ent\xe3o a opera\xe7\xe3o recusada."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo","Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);